    stage: fullDialogStage(lvl("stage")),
    bubble: fullDialogBubble(lvl("bubble")),
    text: fullDialogText(lvl("text", "text", "text_style")),
    typing: fullDialogTyping(lvl("typing")),
    choices: dlgMerge(theme.choices, d && d.choices),
    indicator: dlgMerge(theme.indicator, d && d.indicator),
