  if (reqMissing(d.requirements, c.inventory, c.vars).length) return { ok: false, reason: "conditions" };
  if (d.repeat === "once" && c.seen[d.id]) return { ok: false, reason: "deja vu" };
  return { ok: true, reason: "" };
