    if (!id) return { dialogId: d.id, nodeId: "", done: true, broken: false, effects: effects };
    if (steps++ > DIALOG_MAX_STEPS) return { dialogId: d.id, nodeId: "", done: true, broken: false, loop: true, effects: effects };
    const n = dialogNodeById(d, id);
    if (!n) return { dialogId: d.id, nodeId: "", done: true, broken: true, effects: effects };
    c.seen[d.id + "/" + n.id] = true;
    if (n.type === "line" || n.type === "choice") return { dialogId: d.id, nodeId: n.id, done: false, broken: false, effects: effects };
    if (n.type === "condition") { id = reqMissing(n.requirements, c.inventory, c.vars).length ? n.ifFalse : n.ifTrue; continue; }
    if (n.type === "action") { run(n.actions); id = n.next; continue; }
